#!/usr/bin/env node
// ============================================================================
// Certen Protocol - Non-EVM Chain Balance Checker
// ============================================================================
// Checks balances for all validators across Solana, Aptos, Sui, NEAR, TON.
// Reads addresses from ./output/addresses.json (generated by generate.mjs)
// or accepts addresses via CLI args.
//
// Usage:
//   node check-balances.mjs                    # reads from output/addresses.json
//   node check-balances.mjs addresses.json     # reads from custom file
// ============================================================================

import { readFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// ── RPC Endpoints ───────────────────────────────────────────────────────────
const RPC = {
  solana: process.env.SOLANA_DEVNET_RPC_URL || 'https://api.devnet.solana.com',
  aptos: process.env.APTOS_TESTNET_RPC_URL || 'https://fullnode.testnet.aptoslabs.com/v1',
  sui: process.env.SUI_TESTNET_RPC_URL || 'https://fullnode.testnet.sui.io:443',
  near: process.env.NEAR_TESTNET_RPC_URL || 'https://rpc.testnet.near.org',
  ton: process.env.TON_TESTNET_API_URL || 'https://testnet.toncenter.com/api/v2',
};
const TON_API_KEY = process.env.TON_TESTNET_API_KEY || '';

// ── Helpers ─────────────────────────────────────────────────────────────────
async function jsonRpc(url, method, params) {
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
  });
  const data = await resp.json();
  if (data.error) throw new Error(`${method}: ${JSON.stringify(data.error)}`);
  return data.result;
}

function formatBalance(lamports, decimals, symbol) {
  return `${(Number(lamports) / 10 ** decimals).toFixed(6)} ${symbol}`;
}

// ── Solana Balance ──────────────────────────────────────────────────────────
async function getSolanaBalance(pubkey) {
  try {
    const result = await jsonRpc(RPC.solana, 'getBalance', [pubkey]);
    return formatBalance(result.value, 9, 'SOL');
  } catch (e) {
    return `ERROR: ${e.message}`;
  }
}

// ── Aptos Balance ───────────────────────────────────────────────────────────
async function getAptosBalance(address) {
  try {
    // Use view function (works with both CoinStore and FungibleAsset models)
    const resp = await fetch(`${RPC.aptos}/view`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        function: '0x1::coin::balance',
        type_arguments: ['0x1::aptos_coin::AptosCoin'],
        arguments: [address],
      }),
    });
    if (!resp.ok) {
      const text = await resp.text();
      if (text.includes('ABORTED') || text.includes('not found')) return '0.000000 APT';
      return `ERROR: HTTP ${resp.status}`;
    }
    const data = await resp.json();
    return formatBalance(data[0], 8, 'APT');
  } catch (e) {
    return `ERROR: ${e.message}`;
  }
}

// ── Sui Balance ─────────────────────────────────────────────────────────────
async function getSuiBalance(address) {
  try {
    const result = await jsonRpc(RPC.sui, 'suix_getBalance', [address, '0x2::sui::SUI']);
    return formatBalance(result.totalBalance, 9, 'SUI');
  } catch (e) {
    return `ERROR: ${e.message}`;
  }
}

// ── NEAR Balance ────────────────────────────────────────────────────────────
async function getNEARBalance(accountId) {
  try {
    const result = await jsonRpc(RPC.near, 'query', {
      request_type: 'view_account',
      finality: 'final',
      account_id: accountId,
    });
    return formatBalance(result.amount, 24, 'NEAR');
  } catch (e) {
    if (e.message.includes('does not exist')) return '0.000000 NEAR (account not created)';
    return `ERROR: ${e.message}`;
  }
}

// ── TON Balance ─────────────────────────────────────────────────────────────
async function getTONBalance(address) {
  try {
    const url = new URL(`${RPC.ton}/getAddressBalance`);
    url.searchParams.set('address', address);
    if (TON_API_KEY) url.searchParams.set('api_key', TON_API_KEY);
    const resp = await fetch(url);
    const data = await resp.json();
    if (!data.ok) return `ERROR: ${data.error || data.result || 'unknown'}`;
    const balance = data.result ?? '0';
    return formatBalance(balance, 9, 'TON');
  } catch (e) {
    return `ERROR: ${e.message}`;
  }
}

// ── Main ────────────────────────────────────────────────────────────────────
async function main() {
  // Load addresses
  const addrFile = process.argv[2] || join(__dirname, 'output', 'addresses.json');
  let addresses;
  try {
    addresses = JSON.parse(readFileSync(addrFile, 'utf8'));
  } catch (e) {
    console.error(`Cannot read addresses file: ${addrFile}`);
    console.error('Run "node generate.mjs" first to generate keys, or provide a path.');
    process.exit(1);
  }

  const validators = Object.keys(addresses).sort();
  console.log('Certen Protocol - Non-EVM Balance Checker');
  console.log('=========================================');
  console.log(`Checking ${validators.length} validators x 5 chains...\n`);

  // Header
  const chains = ['Solana', 'Aptos', 'Sui', 'NEAR', 'TON'];
  const totals = { solana: 0, aptos: 0, sui: 0, near: 0, ton: 0 };
  const decimals = { solana: 9, aptos: 8, sui: 9, near: 24, ton: 9 };

  for (const vid of validators) {
    const a = addresses[vid];
    console.log(`\n${vid}:`);

    // Solana
    const solAddr = typeof a.solana === 'string' ? a.solana : a.solana?.publicKey;
    if (solAddr) {
      const bal = await getSolanaBalance(solAddr);
      console.log(`  Solana  ${solAddr.slice(0, 12)}...  ${bal}`);
    } else {
      console.log('  Solana  (no address)');
    }

    // Aptos
    const aptAddr = typeof a.aptos === 'string' ? a.aptos : a.aptos?.address;
    if (aptAddr) {
      const bal = await getAptosBalance(aptAddr);
      console.log(`  Aptos   ${aptAddr.slice(0, 12)}...  ${bal}`);
    } else {
      console.log('  Aptos   (no address)');
    }

    // Sui
    const suiAddr = typeof a.sui === 'string' ? a.sui : a.sui?.address;
    if (suiAddr) {
      const bal = await getSuiBalance(suiAddr);
      console.log(`  Sui     ${suiAddr.slice(0, 12)}...  ${bal}`);
    } else {
      console.log('  Sui     (no address)');
    }

    // NEAR
    const nearAcct = typeof a.near === 'string' ? a.near : a.near?.accountId;
    if (nearAcct) {
      const bal = await getNEARBalance(nearAcct);
      console.log(`  NEAR    ${nearAcct}  ${bal}`);
    } else {
      console.log('  NEAR    (no address)');
    }

    // TON
    const tonAddr = typeof a.ton === 'string' ? a.ton : a.ton?.address;
    if (tonAddr) {
      const bal = await getTONBalance(tonAddr);
      console.log(`  TON     ${tonAddr.slice(0, 12)}...  ${bal}`);
    } else {
      console.log('  TON     (no address)');
    }
  }

  console.log('\n=========================================');
  console.log('Done.');
}

main().catch((err) => {
  console.error('Fatal error:', err);
  process.exit(1);
});
